create table readings (id bigint generated always as identity primary key, org_id integer not null, kind text not null, taken_at timestamptz not null, watts integer, cost numeric(10,2), deleted_at timestamptz);
create index on readings (taken_at);
create index on readings (org_id);
insert into readings (org_id, kind, taken_at, watts, cost, deleted_at)
  select 1 + i % 2, case when i % 3 = 0 then 'heat' else 'power' end, timestamptz '2026-07-01 00:00:00+00' + i * interval '97 seconds',
    case when i % 7 = 0 then null else i % 500 end, (i % 1000) / 100.0, case when i % 11 = 0 then timestamptz '2026-07-05 00:00:00+00' end
  from generate_series(1, 6000) as i;
-- The buckets are UTC hours whatever the session's time zone, here one half an hour off.
set timezone = 'Asia/Kolkata';

-- The schema of the functions that keep rollups and refresh time rollups.
create schema if not exists "rollups";

-- The table and refresh function of a time rollup of readings_hourly.
create table "public"."readings_hourly" as select date_trunc('hour', c."taken_at"::timestamptz) as "bucket", c."org_id" as "org_id", c."kind" as "kind", count(*) as "events", sum(c."watts") as "watts_sum", max(c."watts") as "watts_max", sum(c."cost") as "cost_sum", count(c."watts") as "watts_count", count(c."cost") as "cost_count" from "public"."readings" as c group by 1, 2, 3 with no data;
alter table "public"."readings_hourly" add column "id" bigint generated always as identity primary key, alter column "bucket" set not null, alter column "org_id" set not null, alter column "kind" set not null, alter column "events" set not null, alter column "watts_count" set not null, alter column "cost_count" set not null;
create unique index "readings_hourly_bucket_key" on "public"."readings_hourly" ("bucket", "org_id", "kind");
create index "readings_hourly_org_id_bucket" on "public"."readings_hourly" ("org_id", "bucket");
create index "readings_hourly_kind_bucket" on "public"."readings_hourly" ("kind", "bucket");
comment on table "public"."readings_hourly" is 'protobase time rollup: from "public"."readings" (taken_at timestamp, org_id integer, kind text, watts integer, cost decimal, deleted_at timestamp)';
create or replace function "rollups"."readings_hourly_refresh"("from" timestamptz) returns void language plpgsql set search_path = pg_catalog, pg_temp set timezone = 'UTC' as $buckets$
<<refresh>>
declare
  since "public"."readings"."taken_at"%type := date_trunc('hour', $1);
begin
with fresh as (
  select date_trunc('hour', c."taken_at"::timestamptz) as "bucket", c."org_id" as "org_id", c."kind" as "kind", count(*) as "events", sum(c."watts") as "watts_sum", max(c."watts") as "watts_max", sum(c."cost") as "cost_sum", count(c."watts") as "watts_count", count(c."cost") as "cost_count"
  from "public"."readings" as c
  where c."taken_at" >= refresh.since and c."deleted_at" is null
  group by 1, 2, 3
), gone as (
  delete from "public"."readings_hourly" as r where r."bucket" >= date_trunc('hour', $1) and not exists (select from fresh where fresh."bucket" = r."bucket" and fresh."org_id" = r."org_id" and fresh."kind" = r."kind")
)
insert into "public"."readings_hourly" ("bucket", "org_id", "kind", "events", "watts_sum", "watts_max", "cost_sum", "watts_count", "cost_count")
select "bucket", "org_id", "kind", "events", "watts_sum", "watts_max", "cost_sum", "watts_count", "cost_count" from fresh
on conflict ("bucket", "org_id", "kind") do update set "events" = excluded."events", "watts_sum" = excluded."watts_sum", "watts_max" = excluded."watts_max", "cost_sum" = excluded."cost_sum", "watts_count" = excluded."watts_count", "cost_count" = excluded."cost_count";
end
$buckets$;

-- The table and refresh function of a time rollup of readings_hourly.
select "rollups"."readings_hourly_refresh"('-infinity');

insert into readings (org_id, kind, taken_at, watts, cost) values (1, 'heat', '2026-07-07 15:10:00+00', 40, 1.25), (2, 'wind', '2026-07-07 16:59:59+00', 7, 0.5);
update readings set watts = coalesce(watts, 3) + 1 where taken_at >= '2026-07-07 10:00:00+00';
update readings set cost = null where taken_at >= '2026-07-07 12:00:00+00' and taken_at < '2026-07-07 13:00:00+00';
update readings set deleted_at = '2026-07-08 00:00:00+00' where taken_at >= '2026-07-07 14:00:00+00' and taken_at < '2026-07-07 15:00:00+00';
